<template><WarmDialog :open="open" title="翻到这一天" @close="$emit('close')"><view class="month-nav"><button @click="move(-1)" :disabled="year<=2000&&month===1">‹</button><view class="month-fields"><input aria-label="年份" type="number" v-model="yearInput" maxlength="4" @blur="setYear"/><text>年 {{month}} 月</text></view><button @click="move(1)" :disabled="year>=2099&&month===12">›</button></view><view class="calendar-grid"><text v-for="w in weeks" :key="w" class="weekday">{{w}}</text><view v-for="n in offset" :key="'pad'+n"/><button v-for="day in count" :key="day" :class="{picked:dateKey(day)===selected,today:dateKey(day)===today}" @click="selected=dateKey(day)">{{day}}</button></view><view class="date-footer"><button class="secondary small" @click="jumpToday">今天</button><button class="primary small" @click="$emit('select',selected);$emit('close')">确定日期</button></view></WarmDialog></template>
<script setup>
import {ref,computed,watch} from 'vue';import WarmDialog from './WarmDialog.vue';
const props=defineProps({open:Boolean,value:String});defineEmits(['select','close']);const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10),year=ref(2026),month=ref(1),yearInput=ref('2026'),selected=ref(today),weeks=['一','二','三','四','五','六','日'];
function show(value){const parts=(value||today).split('-');year.value=Number(parts[0]);month.value=Number(parts[1]);yearInput.value=String(year.value);selected.value=value||today;}
watch(()=>props.open,v=>{if(v)show(props.value);});
const count=computed(()=>new Date(Date.UTC(year.value,month.value,0)).getUTCDate()),offset=computed(()=>(new Date(Date.UTC(year.value,month.value-1,1)).getUTCDay()+6)%7);
const dateKey=d=>year.value+'-'+String(month.value).padStart(2,'0')+'-'+String(d).padStart(2,'0');
function move(delta){const d=new Date(Date.UTC(year.value,month.value-1+delta,1));year.value=d.getUTCFullYear();month.value=d.getUTCMonth()+1;yearInput.value=String(year.value);}
function setYear(){year.value=Math.min(2099,Math.max(2000,Number(yearInput.value)||year.value));yearInput.value=String(year.value);}
function jumpToday(){show(today);}
</script>
<style scoped>.month-nav{display:flex;justify-content:space-between;align-items:center;margin-bottom:20rpx}.month-nav>button{background:#ffedba;color:#78552b;padding:4rpx 24rpx;font-size:42rpx}.month-fields{display:flex;gap:8rpx;align-items:center;font-size:26rpx}.month-fields input{width:110rpx;height:64rpx;margin:0;padding:8rpx;text-align:center}.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8rpx}.calendar-grid button{padding:16rpx 0;background:#fff4d8;color:#795d34;font-size:25rpx;border-radius:16rpx}.calendar-grid .picked{background:#eebf59;color:#503b1c;box-shadow:0 3rpx 0 #cba153}.calendar-grid .today{border:2rpx solid #ce9c42}.weekday{text-align:center;font-size:22rpx;color:#b28e4f;padding:10rpx 0}.date-footer{display:flex;justify-content:space-between;margin-top:26rpx;gap:20rpx}</style>
